"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["92125"],{26885(e,t,s){s.r(t),s.d(t,{metadata:()=>n,default:()=>c,frontMatter:()=>l,contentTitle:()=>i,toc:()=>g,assets:()=>o});var n=JSON.parse('{"id":"qiangguo/classstrugglemanual","title":"","description":"Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/classstrugglemanual.md","sourceDirName":"qiangguo","slug":"/qiangguo/classstrugglemanual","permalink":"/en/qiangguo/classstrugglemanual","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"classstrugglemanual","title":"","hide_table_of_contents":true,"sidebar_label":"Class Struggle Handbook 2: How Did \\"Class Struggle\\" Become the Left\'s Underwear!"},"sidebar":"qiangguoSidebar","previous":{"title":"Enthusiastic Applause for Jiangsu\'s Removal of the \\"Strictly Prohibiting Cohabitation of Men and Women Without Marriage Certificate\\" Regulation","permalink":"/en/qiangguo/applaudforjs"},"next":{"title":"Proving That Abstract Human Nature Does Not Exist","permalink":"/en/qiangguo/abstracthumanity"}}'),a=s(74848),r=s(28453);let l={id:"classstrugglemanual",title:"",hide_table_of_contents:!0,sidebar_label:'Class Struggle Handbook 2: How Did "Class Struggle" Become the Left\'s Underwear!'},i='Class Struggle Manual 2: How Did "Class Struggle" Become the Left\'s Underwear!',o={},g=[];function u(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"class-struggle-manual-2-how-did-class-struggle-become-the-lefts-underwear",children:'Class Struggle Manual 2: How Did "Class Struggle" Become the Left\'s Underwear!'})}),"\n",(0,a.jsxs)(t.blockquote,{children:["\n",(0,a.jsx)(t.p,{children:"Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n"}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:'"Class struggle" became the left\'s underwear \u2014 a feat jointly accomplished by both left and right. The reason "class struggle" is in quotation marks here is that in the mouths of both left and right, "class struggle" has become a purely nominal term. Meanwhile, real class struggle exists at every moment in every corner of society, having nothing to do with any faction\'s lip service.'}),"\n",(0,a.jsx)(t.p,{children:'The left waves "class struggle" like underwear on the flagpole of history, peddling the laughable secrets contained within. The right, in turn, makes "class struggle" the last pair of underwear to strip the left naked, always ready to extend that right-wing pig-groping hand, forgetting that the right never wears underwear to begin with. Left and right are always pathetically and pitifully flailing about like this, historically Brokeback Mounting each other.'}),"\n",(0,a.jsx)(t.p,{children:'"Class struggle" as lip service \u2014 the emperor\'s underwear \u2014 signifies nothing beyond the ambiguous tedium of left and right. But real class struggle is reality itself, is history itself. It needs no factions, no lip service. It stands perpetually erect, needing no concealment, carrying the most primal cruelty and pleasure, class-struggling away.'}),"\n",(0,a.jsx)(t.p,{children:'There is a laughable claim called "the expansion of class struggle." Yet class struggle exists at every moment in every corner of society, permeating every possible human reality \u2014 what is left to expand? Every corner of reality is the beginning, process, and result of class struggle, with nowhere to escape. Even the verbal declaration that class struggle doesn\'t exist is itself part of class struggle \u2014 what then has nothing to do with class struggle?'}),"\n",(0,a.jsx)(t.p,{children:"Class struggle needs no expansion and cannot be contracted \u2014 it can only be faced in reality. Food and sex \u2014 these most primal aspects of human existence are thoroughly permeated by class struggle. From each person's daily food and dining manner, we can see the divisions and struggles of class. In the distribution and possession of sexual resources, we can see these class divisions and struggles even more clearly. This requires no lip service, no jargon \u2014 it is on display at every moment in every corner of the world."})]})}function c(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(u,{...e})}):u(e)}},28453(e,t,s){s.d(t,{R:()=>l,x:()=>i});var n=s(96540);let a={},r=n.createContext(a);function l(e){let t=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:l(e.components),n.createElement(r.Provider,{value:t},e.children)}}}]);